function _to_cpu_gauge(U::Vector{G}) where {G<:AbstractGaugefields}

        NC = U[1].NC
        NX = U[1].NX; NY = U[1].NY; NZ = U[1].NZ; NT = U[1].NT
        Ucpu = Initialize_Gaugefields(NC, 0, NX, NY, NZ, NT, condition="cold")
        try
