function _to_gpu_hop(hop::Hopping_operator; blocks=nothing)
    Ugpu = _to_gpu_gauge(hop.Gauge; blocks=blocks)
    if Ugpu === hop.Gauge
        return hop
    end
    return Hopping_operator(Ugpu, hop.P)
end

