function  (layer::Attention_Layer)(x::WF3x1)


    QW=Clifford(layer.Q.W)
    KW=Clifford(layer.K.W)
    VW=Clifford(layer.V.W)

    lW=length(QW)


    m=layer.nominator


    Hx=layer.V.hop(x)



    Q=similar(x)
    K=similar(x)
    M=similar(QW)
    S=similar(QW)
    for i in 1:lW
        mul!(Q,QW[i],Hx[i])
        mul!(K,KW[i],Hx[i])

        S[i]=layer.activation(Matmul!(conj(Q),K)/m)
        # M[i]=Matmul!(conj(Q),K)/m
        # println("M[$(i)]: ", M[i])
        # println("S[$(i)]: ", S[i])

    
    end 

    for i in 1:lW
        mul!(S[i],S[i],VW[i])
    end




    z=similar(x)
    

    temp =similar(x)
    for i in 1:length(KW)
        mul!(temp,S[i],Hx[i])
        axpby!(1,temp,1,z)
    end



    if layer.residual == true 
        # z=z+x
        axpby!(1,x,1,z)
    end 
    return z




end




