function (D::Dirac_Layer)(x::WF3x1)

    Dirac=D.activation
    y=Dirac*x
    return y
end 

function (layer::PrallelTransportAttention_Layer)(x::WF3x1)

    # QW=layer.Q.W
    KW=layer.K.W
    VW=layer.V.W

    lW=length(KW)
    m=layer.nominator
    b=layer.bias

    Kx=KW*layer.K.hop(x)
    # Qx=QW*layer.Q.hop(x)
    Hx=layer.V.hop(x)
    M=similar(KW)
    S=similar(KW)
    R=similar(KW)


    for i in 1:lW
        M[i]=Matmul!(conj(Hx[1]),Kx[i])/m
        for a in 1:4
            R[i][a,a]=abs(M[i][a,a])
        end

    end 

    ratio = zeros(Float64, 4)           # 鬯ｯ・ｯ繝ｻ・ｯ郢晢ｽｻ繝ｻ・ｮ驛｢譎｢・ｽ・ｻ郢晢ｽｻ繝ｻ・ｫ鬩幢ｽ｢隴趣ｽ｢繝ｻ・ｽ繝ｻ・ｻ驛｢譎｢・ｽ・ｻ郢晢ｽｻ繝ｻ・ｨ鬯ｩ蟷｢・ｽ・｢髫ｴ雜｣・ｽ・｢郢晢ｽｻ繝ｻ・ｽ郢晢ｽｻ繝ｻ・ｻ鬩幢ｽ｢隴趣ｽ｢繝ｻ・ｽ繝ｻ・ｻ驛｢譎｢・ｽ・ｻ郢晢ｽｻ繝ｻ・ｨ鬯ｯ・ｯ繝ｻ・ｩ髯晢ｽｷ繝ｻ・｢郢晢ｽｻ繝ｻ・ｽ郢晢ｽｻ繝ｻ・｢鬯ｮ・ｫ繝ｻ・ｴ鬮ｮ諛ｶ・ｽ・｣郢晢ｽｻ繝ｻ・ｽ郢晢ｽｻ繝ｻ・｢鬩幢ｽ｢隴趣ｽ｢繝ｻ・ｽ繝ｻ・ｻ驛｢譎｢・ｽ・ｻ郢晢ｽｻ繝ｻ・ｽ鬩幢ｽ｢隴趣ｽ｢繝ｻ・ｽ繝ｻ・ｻ驛｢譎｢・ｽ・ｻ郢晢ｽｻ繝ｻ・ｻ



    for u in 1:lW
        for a in 1:4
            ratio[a]+=R[u][a,a]
        end
    end

    for i in 1:lW
        for a in 1:4
            val = max(real(R[i][a,a] / ratio[a] - b),0)
            S[i][a,a]=val*M[i][a,a]
        end
    end

 

    # println("ratio: ", ratio[2])

    W=S*VW
    z=similar(x)




    temp= similar(x)

    for i in 1:length(KW)
        mul!(temp,W[i],Hx[i])
        axpby!(1,temp,1,z)
    end

    if layer.residual == true 
        # z=z+x
        axpby!(1,x,1,z)
    end



    return z
end 

function (layer::siteweight_Layer)(x::WF3x1)

    QW=layer.Q.W
    KW=layer.K.W
    VW=layer.V.W

    lW=length(KW)
    m=layer.nominator


    Hx=layer.V.hop(x)

    Kx=KW*layer.K.hop(x)
    Qx=QW*layer.Q.hop(x)
    
    Hx=layer.V.hop(x)
    Vx=VW*layer.V.hop(x)

    result = similar(x)
    for p in 1:lW
        a=similar(x)
        S=Vector{Array{ComplexF64, 4}}(undef, lW)
        for q in 1:lW
            S[q] = spincolortrace(conj(Qx[p]), Kx[q]) / m
            # n=norm(vec(S[q]))
            # S[q]=S[q]/n
            a += S[q] * Vx[q]

        end
        result += a
    end 




    if layer.residual == true 
        # result=result+x
        axpby!(1,x,1,result)
    end

    return result
end


function (layer::HoppingRayleighQuotient_Layer)(D::Dirac_operator)


    x=layer.x

    Hx=layer.hop(x)

    y=similar(x)
    for i in 1:length(Hx)
        axpby!(1,Hx[i],1,y)
    end
    u=D*y
    
    rq=inner_product(u,u)/inner_product(y,y)
    
    return rq
end


