function (L::LossSumLayer)(x::AbstractVector{<:WF3x1})
    return L.w1 * L.l1(x) + L.w2 * L.l2(x)
end


function Base.:+(a::A, b::B) where {A<:Layer, B<:Layer}
    return LossSumLayer(a, b)
end


function (layers::Vector{T})(x::Any) where T<:Layer
    result = x
    for layer in layers
        result = layer(result)
    end
    return result
end


